/* buyer.mpso.updateAppStatus */
UPDATE ICOMPRDT A
   SET RECV_FLAG   = #{st_app_flag}
     , STATUS      = 'R'
     , IV_COLUMN	= #{docnum}
     , CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
     , CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')
 WHERE A.BUYER = #{st_buyer}
   AND A.PR_NO = #{st_doc_no}

/* buyer.mpso.updateApprovalConfirm */
UPDATE ICOMPRDT A
   SET SAVE_FLAG    = 'PX'
     , RECV_QTY     = TARGET_QTY
     , PURCHASER_ID = NVL((SELECT USER_ID FROM ICOMLUSR WHERE COM_CODE = A.BUYER AND LEGACY_USER_ID = #{PEmpCode} AND ROWNUM = 1), #{PEmpCode})
     , IV_COLUMN	= #{docnum}
     , REF_NO       = #{st_ref_no}
     , REF_SEQ      = PR_SEQ
     , STATUS       = 'R'
     , CHANGE_DATE  = TO_CHAR(SYSDATE,'YYYYMMDD')
     , CHANGE_TIME  = TO_CHAR(SYSDATE,'HH24MISS')
 WHERE A.BUYER = #{st_buyer}
   AND A.PR_NO = #{st_doc_no}

/* buyer.mpso.updateExternAppStatus */
UPDATE ICOMPRDT A
   SET RECV_FLAG   = #{recv_flag}
     , STATUS      = 'R'
     , CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
     , CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')
 WHERE A.BUYER = #{st_buyer}
   AND A.PR_NO = #{st_pr_no}

/* buyer.mpso.updateExternApprovalConfirm */
UPDATE ICOMPRDT A
   SET SAVE_FLAG    = 'PX'
     , RECV_FLAG    = 'PS'
     , RECV_QTY     = TARGET_QTY
     , PURCHASER_ID = NVL((SELECT USER_ID FROM ICOMLUSR WHERE COM_CODE = A.BUYER AND LEGACY_USER_ID = #{st_user_id} AND ROWNUM = 1), #{st_user_id})
     , REF_NO       = #{st_ref_no}
     , REF_SEQ      = PR_SEQ
     , STATUS       = 'R'
     , CHANGE_DATE  = TO_CHAR(SYSDATE,'YYYYMMDD')
     , CHANGE_TIME  = TO_CHAR(SYSDATE,'HH24MISS')
 WHERE A.BUYER = #{st_buyer}
   AND A.PR_NO = #{st_pr_no}

