/* buyer.mpso.selectAeroIFAppPrList */ SELECT A.BUYER, B.COM_NAME_LOC, A.PR_NO, A.PR_SEQ, A.BUYER_ITEM_NO, SUBSTRB(A.DESCRIPTION,1,100) AS DESCRIPTION, NVL(A.SPECIFICATION,' ') AS SPECIFICATION, 'KRW' AS CUR, A.UNIT_MEASURE, NVL((SELECT NVL(TEXT1,' ') FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND TYPE = 'C001' AND CODE = A.BUDGET_DEPT), ' ') AS BUDGET_DEPT, NVL((SELECT NVL(TEXT1,' ') FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND TYPE = 'Z014' AND CODE = A.ACCOUNT_TYPE), ' ') AS ACCOUNT_TYPE, TO_CHAR(TO_DATE(A.ADD_DATE,'YYYYMMDD'),'YYYY-MM-DD') AS ADD_DATE, TO_CHAR(TO_DATE(A.RD_DATE,'YYYYMMDD'),'YYYY-MM-DD') AS RD_DATE, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = CASE WHEN B.AGENT_OPEN_FLAG = 'Y' THEN A.AGENT ELSE 'KRKORE0001' END ) AS AGENT_NAME, TRIM(TO_CHAR(A.TARGET_QTY,'999,999,999,999,999')) AS TARGET_QTY, TRIM(TO_CHAR(A.TARGET_PRICE,'999,999,999,999,999')) AS PRICE, TRIM(TO_CHAR((A.TARGET_QTY * A.TARGET_PRICE) ,'999,999,999,999,999')) AS AMT, NVL(A.LEGACY_PO_NO , ' ') AS LEGACY_PO_NO , NVL(C.USER_NAME_LOC,' ') AS USER_NAME_LOC , NVL(F_SPLIT(D.DESCRIPT,'^',1), ' ') AS ERP_ITEM_NO, TRIM(TO_CHAR(SUM(A.TARGET_QTY * A.TARGET_PRICE) OVER() ,'999,999,999,999,999')) AS AMT_TOTAL FROM ICOMPRDT A , ICOMCMPY B , ICOMLUSR C , ICOMBYCA D WHERE 1 = 1 AND A.BUYER = #{buyer} AND A.PR_NO = #{sPR_No}
AND A.BUYER = B.COM_CODE
AND C.COM_CODE = A.BUYER AND C.USER_ID = A.PURCHASER_ID
AND D.COM_CODE = A.BYIT_COMORG_CODE AND D.STD_CATEG_ID = A.CATEG_ID

