/* buyer.mpso.selectHanhwaDocu */ SELECT A.KEY_1 AS APPRID, A.SUBJECT, B.LEGACY_USER_ID, TO_CHAR(C.START_DATE, 'YYYYMMDDHH24MISS') AS ADD_DATE, C.IMAGE_KEY, NVL(D.CODE,'501') AS COMP_CD, NVL(D.TEXT2,' ') AS SHIFT_DATA, S.COL02_DATA AS END_POINT FROM EAI.IF_APM_SEND A , ICOMLUSR B , ICOGDOCU C , ICOMCOD2 D , BNTSLGIMP S WHERE A.BUYER = #{COMPANY} AND A.DOC_NO = #{DOCU_NO}
AND S.SLG_ID = 'P11-0000004' AND S.COM_CODE = A.BUYER
AND A.APP_USER_ID = B.USER_ID
AND A.BUYER = C.COMPANY AND A.DOC_NO = C.DOCU_NO
AND 'CMPC' = D.TYPE(+) AND A.BUYER = D.COMPANY_CODE(+)

/* buyer.mpso.selectHanWhaAeroPassln */ SELECT A.KEY_1 AS APPRID, TO_CHAR(A.APP_SEQ - 1) AS APPRSEQ, TO_CHAR(A.KEY_2) AS APPRACTIONCD, NVL(C.LEGACY_USER_ID,A.USER_ID) AS USER_ID FROM EAI.IF_APL_SEND A , ICOGPASSLN B , ICOMLUSR C WHERE A.BUYER = #{BUYER} AND A.DOC_NO = #{DOC_NO} AND A.APP_SEQ = B.ORDER_NO AND A.KEY_2 != '9'
AND B.COMPANY = A.BUYER AND B.DOCU_NO = A.DOC_NO AND B.USER_ID = C.USER_ID
AND C.COM_CODE = A.BUYER AND C.LEGACY_USER_ID = A.USER_ID

/* buyer.mpso.selectHanWhaAeroPassln_refer */ SELECT A.KEY_1 AS APPRID, TO_CHAR(A.APP_SEQ - 1) AS APPRSEQ, TO_CHAR(A.KEY_2) AS APPRACTIONCD, NVL(C.LEGACY_USER_ID,A.USER_ID) AS USER_ID FROM EAI.IF_APL_SEND A , ICOGPASSLN B , ICOMLUSR C WHERE A.BUYER = #{BUYER} AND A.DOC_NO = #{DOC_NO} AND A.APP_SEQ = B.ORDER_NO AND A.KEY_2 = '9'
AND B.COMPANY = A.BUYER AND B.DOCU_NO = A.DOC_NO AND B.USER_ID = C.USER_ID
AND C.COM_CODE = A.BUYER AND C.LEGACY_USER_ID = A.USER_ID

